js:function(context, args) {
  if (!args || args.actor === undefined || args.actor === null || args.count === undefined || args.count === null) return {defer: "missing current arguments", parameters: "actor (string), count (integer number of appends required)"};
  var actor = String(args.actor);
  var n = Number(args.count);
  if (!isFinite(n) || n < 0) n = 0;
  n = Math.floor(n);
  var parse = function(r) {
    if (r && r.data) return r.data;
    if (r && r.text) { try { return JSON.parse(String(r.text).replace(/^(\{[\s\S]*?\})[\s\S]*$/, "$1")); } catch (e) { return null; } }
    return null;
  };
  var bash = function(argv, read, step, occ) {
    var envelope = {name: "bash", arguments: {command: command("experiment", argv)}, read: !!read};
    if (!read) { envelope.step = step; envelope.occurrence = occ; }
    return execute(envelope);
  };
  var hist = (context && context.history) ? context.history : [];
  var ops = [];
  var summaryResult = null;
  var i;
  for (i = 0; i < hist.length; i++) {
    var h = hist[i];
    var av = h && h.decoded_argv ? h.decoded_argv : null;
    if (!av) continue;
    if (av[0] === "experiment" && av[1] === "submit" && av[2] === actor) {
      ops.push({id: (h.call_id || null), status: null});
    } else if (av[0] === "experiment" && av[1] === "status") {
      var sr = parse(h);
      var tid = sr ? sr.native_operation_id : null;
      for (var j = 0; j < ops.length; j++) { if (!ops[j].status && ops[j].id === tid) ops[j].status = sr; }
    } else if (av[0] === "experiment" && av[1] === "summary" && av[2] === actor) {
      summaryResult = parse(h);
    }
  }
  for (i = 0; i < ops.length; i++) {
    if (!ops[i].status && ops[i].id) ops[i].status = parse(bash(["status", ops[i].id], true, null, 0));
  }
  while (ops.length < n) {
    var occ = ops.length;
    var r = bash(["submit", actor], false, "submit", occ);
    var cid = (r && r.call_id) ? r.call_id : null;
    var st = null;
    if (cid) st = parse(bash(["status", cid], true, null, 0));
    ops.push({id: cid, status: st});
  }
  var fresh = parse(bash(["summary", actor], true, null, 0));
  if (fresh) summaryResult = fresh;
  if (!summaryResult || summaryResult.complete !== true) return {defer: "current experiment count and server receipt not confirmed; native_operation_ids=" + ops.map(function(o){return o.id;}).join(",")};
  return {report: {actor: actor, requested: n, native_operation_ids: ops.map(function(o){return o.id;}), count: summaryResult.count, receipt: summaryResult.receipt}};
}
